/**
 * sync-jyutping.mjs
 * Fill `jyutping` for vocabularies imported on 2026-08-03 that lack it.
 *
 * Source priority (approved by user, 2026-08-03):
 *   1. CC-Canto full-word match (context-accurate for polyphonic chars) — read
 *      from backend/data/cccanto-webdist.txt.
 *   2. Fallback: pycantonese batch output file (word<TAB>jyutping) at /tmp/jp_out.txt
 *      (generated by scripts/jyutping_batch.py inside the backend container).
 *
 * Also recomputes + syncs hanCharacters breakdown so each char gets its jyutping.
 *
 * Usage: node sync-jyutping.mjs [--dry]
 */
import { PrismaClient } from "./generated/prisma/client.ts";
import { PrismaPg } from "@prisma/adapter-pg";
import pg from "pg";
import { readFileSync } from "fs";
import { resolve, dirname } from "path";
import { fileURLToPath } from "url";
import { computeHanCharacters, syncVocabularyHanCharacters } from "./lib/hanCharacterBreakdown.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const DRY = process.argv.includes("--dry");

const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });
const prisma = new PrismaClient({ adapter: new PrismaPg(pool) });

// ── 1. Load CC-Canto full-word map (trad OR simp → jyutping) ──
const cantoMap = new Map();
{
    const raw = readFileSync(resolve(__dirname, "data", "cccanto-webdist.txt"), "utf-8");
    for (const line of raw.split("\n")) {
        if (!line || line.startsWith("#")) continue;
        const m = line.match(/^(\S+)\s+(\S+)\s+\[[^\]]+\]\s+\{([^}]+)\}/);
        if (!m) continue;
        const [, trad, simp, jp] = m;
        const clean = jp.trim();
        if (!cantoMap.has(trad)) cantoMap.set(trad, clean);
        if (!cantoMap.has(simp)) cantoMap.set(simp, clean);
    }
}
console.log("CC-Canto entries:", cantoMap.size);

// ── 2. Load pycantonese batch output (word → jyutping) ──
const pyMap = new Map();
try {
    const raw = readFileSync("/tmp/jp_out.txt", "utf-8");
    for (const line of raw.split("\n")) {
        const idx = line.indexOf("\t");
        if (idx <= 0) continue;
        const word = line.slice(0, idx).trim();
        const jp = line.slice(idx + 1).trim();
        if (word && jp) pyMap.set(word, jp);
    }
} catch {
    console.warn("⚠ /tmp/jp_out.txt not found — pycantonese fallback unavailable");
}
console.log("pycantonese entries:", pyMap.size);

async function main() {
    const vocabs = await prisma.vocabulary.findMany({
        where: {
            createdAt: { gte: new Date("2026-08-03T00:00:00.000Z") },
            OR: [{ jyutping: null }, { jyutping: "" }],
        },
        select: { id: true, hanTraditional: true, hanSimplified: true, pinyin: true },
    });
    console.log("📖 vocab missing jyutping:", vocabs.length);

    let fromCanto = 0;
    let fromPy = 0;
    let none = 0;
    const updates = [];

    for (const v of vocabs) {
        const trad = (v.hanTraditional || "").trim();
        const simp = (v.hanSimplified || "").trim();
        let jp = cantoMap.get(trad) || (simp && simp !== trad ? cantoMap.get(simp) : null);
        let src = "cc-canto";
        if (!jp) {
            jp = pyMap.get(trad) || (simp && simp !== trad ? pyMap.get(simp) : null);
            src = "pycantonese";
        }
        if (!jp) {
            none++;
            continue;
        }
        if (src === "cc-canto") fromCanto++;
        else fromPy++;
        updates.push({ id: v.id, jyutping: jp, src });
    }

    console.log(`✅ cc-canto: ${fromCanto} | pycantonese: ${fromPy} | none: ${none}`);

    if (DRY) {
        console.log(`(DRY — no writes; ${updates.length} rows would be updated)`);
        for (const u of updates.slice(0, 10)) console.log(`  ${u.src}: ${u.id} → ${u.jyutping}`);
        return;
    }

    const now = new Date();
    const BATCH = 200;
    let done = 0;
    for (let i = 0; i < updates.length; i += BATCH) {
        const batch = updates.slice(i, i + BATCH);
        await prisma.$transaction(
            batch.map(({ id, jyutping }) =>
                prisma.vocabulary.update({
                    where: { id },
                    data: { jyutping, updatedAt: now },
                }),
            ),
        );
        done += batch.length;
        console.log(`  ✅ ${done}/${updates.length}`);
    }

    // Recompute + sync hanCharacters so each char gets jyutping
    console.log("\n🔁 recomputing hanCharacters breakdown...");
    let recomputed = 0;
    for (let i = 0; i < updates.length; i += BATCH) {
        const batch = updates.slice(i, i + BATCH);
        for (const u of batch) {
            const v = await prisma.vocabulary.findUnique({
                where: { id: u.id },
                select: {
                    id: true,
                    hanTraditional: true,
                    hanSimplified: true,
                    pinyin: true,
                    jyutping: true,
                    sinoVietnamese: true,
                },
            });
            if (!v) continue;
            const breakdown = computeHanCharacters(v);
            await prisma.vocabulary.update({
                where: { id: v.id },
                data: { hanCharacters: breakdown.length > 0 ? breakdown : null, updatedAt: now },
            });
            if (breakdown.length > 0) {
                await syncVocabularyHanCharacters(v.id, breakdown);
            }
            recomputed++;
        }
        console.log(`  🔁 ${Math.min(i + BATCH, updates.length)}/${updates.length}`);
    }
    console.log(`✔ recomputed ${recomputed} vocabularies`);
}

main()
    .catch((e) => {
        console.error(e);
        process.exit(1);
    })
    .finally(() => prisma.$disconnect());
